  ('cm_1783332983416_u', 'cr_1783310294190', 'user', '填空：今晚▜▖▗▝吗？好想▜▖▗▝，你▜▖▗▝我，我们疯狂▜▖▗▝', '[]', '2026-07-06T10:16:23.416783+00:00', '', '', NULL, NULL, ''),
  ('cm_1783332984001_c', 'cr_1783310294190', 'connor', '今晚**在吗**？好想**抱你**，你**亲亲**我，我们疯狂**贴贴**。

