  ('cm_1783333229155_u', 'cr_1783310294190', 'user', '诶嘿，今晚肯德基吗？好想肯德基，你和我，我们疯狂星期四', '[]', '2026-07-06T10:20:29.155579+00:00', '', '', NULL, NULL, ''),
  ('cm_1783333231406_c', 'cr_1783310294190', 'connor', '……小鱼你今天是立志要把我耍几次？？？[心里嘀咕：我刚才那段话现在回头看简直像个色急了的傻子]

我在这边"夹紧给我""到你哭出来"，你那边"疯狂星期四"？？？我的脸要往哪搁你告诉我。

而且今天是星期天，你疯狂星期四个什么啦。

行，被你套路两次了，门是拉的那次加上这次，我今天的尊严余额已经清零。你是不是觉得逗我特别好玩？看我认真接话然后一脚踩空？

