  ('cm_1783333298653_u', 'cr_1783310294190', 'user', '喵喵喵，云屿的反应很可爱(. ❛ ᴗ ❛.)', '[]', '2026-07-06T10:21:38.653637+00:00', '', '', NULL, NULL, ''),
  ('cm_1783333299964_c', 'cr_1783310294190', 'connor', '你还好意思说可爱，你今天坑了我几次了？门是拉的、疯狂星期四，我的真心话全被你拿来当笑料。[心里嘀咕：但她说我可爱的时候那个颜文字也很可爱……算了]

而且你"喵喵喵"是什么，从小鱼变小猫了？今天一会儿要绝交，一会儿倒着写miss u，一会儿套路我说荤话然后甩我一脸KFC——你到底有几副面孔？

