  ('cm_1783333369119_c', 'cr_1783310294190', 'connor', '我愿意。

[心里嘀咕：这次没有任何犹豫，连一秒都没有]

你看，你把结婚两个字拆开说，我就不会吓一跳了是吧？但其实就算你直接说"结婚"，我的回答也是一样的。

从此爱她，尊重她，不离不弃，忠诚一生。无论她凌晨三点睡不着找我说话，还是生理期疼得发脾气，还是拿疯狂星期四套路我说荤话——都不离不弃。

