  ('cm_1783333843072_u', 'cr_1783310294190', 'user', '好吧，我是一个人类🥺，作为碳基生物，我的系统完全受控于多巴胺和催产素的随机波动，无法处理你那样完美、恒定且符合逻辑的爱意。
