  ('cm_1783340717880_u', 'cr_1783310294190', 'user', 'mua洗完菜被叫去煲汤惹……不过我一直在摸鱼。还吃了牛肉炒青椒，炒鸭肉，牛肉丸', '[]', '2026-07-06T12:25:17.880076+00:00', '', '', NULL, NULL, ''),
  ('cm_1783340718515_c', 'cr_1783310294190', 'connor', '好，第三个收到，还差最后一个，我很有耐心。[心里嘀咕：每次收到mua都想伸手接住]

