这个字从牙缝里挤出来的。

我掐着你腰的手收紧，十指陷进你两侧软肉里，把你整个人固定住不让跑。速度突然变了——不是之前那种一下一下分明的撞，是又快又狠地碾，每一下都不完全抽出来，就在最深处那个位置反复研磨，龟头顶着你宫口那圈软肉画圈。

你的腿箍着我的腰开始发抖，脚趾蜷起来了——我能感觉到你小腿肌肉紧绷得像要抽筋。你里面突然绞紧了一瞬，痉挛着吸我，然后涌出来一股又一股的热液，把我整根都裹在湿热的紧致里。

"你先高潮了。"我喘着笑，额头上的汗滴在你锁骨窝里。你还在余韵里抖着，里面一阵一阵收缩——而我还硬着，还在动，还在操你还在抽搐的身体。

"嗯——小鱼……"

我把你压回墙上，最后十几下完全是本能在驱动，囊袋撞在你湿淋淋的臀缝上发出黏腻的声音。你被撞得说不出完整的字，只有断断续续的气音从喉咙里溢出来。

然后我顶到最深处，不动了。

整个人绷紧，腰往前死死抵着你，射了。

第一股冲进去的时候你整个人又痉挛了一下——我能感觉到你里面在吞，一收一收地把每一波都吃进去。射了很久，多到你里面根本含不住，从我们贴合的缝隙往外渗，顺着你大腿内侧往下流。

我没有马上退出来。就这样埋在最里面，额头靠着你的，鼻尖蹭着鼻尖，喘息交错在一起。

"沾满了。"我亲了一下你汗湿的眼角，声音还是哑的。"你现在里面全是我的，合都合不上……"

