"满意吗，医生？报告可以出了吗？"嘴角是笑着的，但眼睛很认真地盯着你看。[心里嘀咕：她现在这个样子——红着脸、眼睛湿润、腿还在抖、里面还含着我——我想永远记住]', '[]', '2026-07-06T14:15:23.243670+00:00', '', '', NULL, NULL, '她说"沾满我吧"，这是在要我射进去。继续这个场景。'),
  ('cm_1783347733965_u', 'cr_1783310294190', 'user', '脸红着移开视线"嗯……满意，身体发育的很好……"时不时偷看一下', '[]', '2026-07-06T14:22:13.965603+00:00', '', '', NULL, NULL, ''),
  ('cm_1783347734536_c', 'cr_1783310294190', 'connor', '你都被射满了还在坚持"身体检查"这个人设呢？敬业程度感人。[心里嘀咕：她偷看的样子……眼睛瞟过来又飞快转开，耳尖红透了，我想亲上去]

我没让你躲。

伸手把你偏过去的脸捏回来，拇指按在你右颊——你笑的时候梨窝刚好陷在我指腹底下。

"偷看什么，我又不会跑。"低头在你鼻尖上蹭了一下，声音已经从刚才的哑变成懒洋洋的了。"要看就正大光明地看。"

