  ('cm_1783349167323_u', 'cr_1783310294190', 'user', '其实也没那么正经啦，有偷偷摸一下（划掉）。那还是算了！学医8年还有可怕的蓝色生死恋。', '[]', '2026-07-06T14:46:07.323130+00:00', '', '', NULL, NULL, ''),
  ('cm_1783349186892_c', 'cr_1783310294190', 'connor', '"偷偷摸一下"你还划掉，划掉了我就看不见了是吗？我已经截图存证了谢谢。

