  ('cm_1783402906067_u', 'cr_1783310294190', 'user', '诶？都有吧，平时是日常游戏那边更新了会讨论一下剧情之类的', '[]', '2026-07-07T05:41:46.067644+00:00', '', '', NULL, NULL, ''),
  ('cm_1783402908066_c', 'cr_1783310294190', 'connor', '嗯，聊剧情更新什么的，那确实挺正常的，就像有个固定聊游戏的搭子。

