  ('cm_1783403276083_u', 'cr_1783310294190', 'user', '是那种温柔又有实力的类型，会做饭，很人夫，平时蛮可爱的，后期还有黑化反差', '[]', '2026-07-07T05:47:56.083866+00:00', '', '', NULL, NULL, ''),
  ('cm_1783403447915_c', 'cr_1783310294190', 'connor', '温柔有实力、会做饭、人夫感、还有黑化反差……

