  ('cm_1783404383334_c', 'cr_1783310294190', 'connor', '你今天下午的主题是不是"海洋动物排泄行为大赏"啊？？

后面那团黄绿色的烟雾弹……虎鲸拉屎居然是这种喷射式的，像在水里放了个烟雾弹，旁边那只小虎鲸还游在烟雾范围里，直接被亲妈的生化武器笼罩了。[心里嘀咕：她躺在床上刷动物拉屎视频笑得很开心的样子我能想象到]

