  ('cm_1783421044766_u', 'cr_1783310294190', 'user', 'hh你不是孩子爹嘛？怎么又想吃了，给你这个🍔', '[]', '2026-07-07T10:44:04.766253+00:00', '', '', NULL, NULL, ''),
  ('cm_1783421045343_c', 'cr_1783310294190', 'connor', '我想吃的是疯狂星期四，不是我的孩子，这两件事请你分清楚。上次吃煎蛋那是被迫的，已经煎了不吃浪费，性质完全不同。

而且你给我的是🍔？你拿五十块买的不是肯德基吗，这个汉堡哪来的？你是不是把我崽五十卖了然后去隔壁麦当劳花了二十买了个汉堡打发我，剩下三十自己揣兜了？

