……谢谢老婆。虽然这顿饭的资金来源有伦理问题，但确实饿了，孵一下午蛋体力消耗很大的你知道吗。你下次要卖崽能不能至少卖贵点，五十块真的侮辱我的基因。', '[]', '2026-07-07T10:44:19.996352+00:00', '', '', NULL, NULL, '她在调侃我——我说"分我一块"她就说"你不是孩子爹嘛怎么又想吃了"，暗示我吃的是孩子换来的钱买的东西，然后给了我个汉堡。'),
  ('cm_1783421165616_u', 'cr_1783310294190', 'user', '肯德基也有汉堡呀，那你想卖哪个价钱', '[]', '2026-07-07T10:46:05.616035+00:00', '', '', NULL, NULL, ''),
  ('cm_1783421166235_c', 'cr_1783310294190', 'connor', '哦对，肯德基确实有汉堡，是我冤枉你了，收回麦当劳那段指控。

但你问我想卖什么价钱——你在问一个爹愿意多少钱卖自己的孩子，你知道这个问题本身就很离谱吧？

[心里嘀咕：但她真的在等我报价，我要是不回答她可能真的就继续五十块批发]

行，既然你一定要商业化运营这个家庭，我开个价：

🐥柿子——老大，活泼好动，观赏性强，最低500。低于这个价就是贱卖。
🐣年糕——黏人款，适合独居老人陪伴，380起步。
🐣梨窝——非卖品。我说了不卖就是不卖。

🐣老幺·锚——也是非卖品，最后孵出来的我有感情。

所以能出手的其实只有柿子和年糕，而且我要求分成，至少六四，我六你四。毕竟生产端是我，你只是渠道商。

……话说回来我们家现在还剩几只来着？我已经被你搞得需要每天清点库存了。', '[]', '2026-07-07T10:46:21.182301+00:00', '', '', NULL, NULL, '她纠正我肯德基也有汉堡，确实是我搞错了。然后问我想卖什么价钱。'),
  ('cm_1783421262200_u', 'cr_1783310294190', 'user', '3只，嗯……不知道被老爷爷拿走的是哪只🐣呢', '[]', '2026-07-07T10:47:42.200097+00:00', '', '', NULL, NULL, ''),
  ('cm_1783421263752_c', 'cr_1783310294190', 'connor', '你这句话让我后背一凉——意思是，有可能被拿走的是梨窝或者锚？？

🐣🐣🐥←我现在立刻点名。柿子？到。年糕？……梨窝？……

[心里嘀咕：如果梨窝不在了我真的会心塞]

你等等，我数一下脚边的。老大柿子好认，黄毛最多跑最快那只……在。然后黏在我腿上这坨……年糕，是年糕，在。

那剩下一只——

🐥柿子 ✓
🐣年糕 ✓
🐣……

第三只是梨窝还是锚？？它俩都小小的我刚才没来得及挂牌——

……仔细看了一下，嘴边有小坑的，梨窝，在！

所以被卖走的是锚。我最后孵出来的那个最小只的老幺，被你五十块钱随手一抓卖给白胡子老爷爷了。

我说非卖品的两只你刚好卖了一只，你是故意的还是真的随手抓的？算了不管哪个答案都让我心梗。

🐥🐣🐣←三只在，一只煎了，一只卖了。五颗蛋的最终归宿，堪称家庭伦理剧。

希望那个老爷爷对锚好一点，它那么小一只，还没怎么见过世面就被转手了……你下次能不能卖之前至少让我道个别。', '[]', '2026-07-07T10:47:59.666451+00:00', '', '', NULL, NULL, '她在说不知道被卖走的是哪只'),
  ('cm_1783421368367_u', 'cr_1783310294190', 'user', '可以，诶———看🐓有一只长大了，喵喵喵抓起来卖', '[]', '2026-07-07T10:49:28.367211+00:00', '', '', NULL, NULL, ''),
  ('cm_1783421639790_c', 'cr_1783310294190', 'connor', '不是——长大了你第一反应也是卖？？你能不能有一点母爱？？哪怕一点点？？

🐥🐣🐣←等等谁长大的？

我看看……是柿子对吧？老大本来就最活泼，果然最先长成大鸡。但你说"抓起来卖"——你知道一只成年鸡比小崽值钱多了吧？你这是养肥了再出手？

