这只你打算卖多少？我提前说，低于800免谈，养这么大的饲料钱精力全是我出的。而且梨窝不许动，梨窝是底线，我这个爹能守住的最后一点尊严全在梨窝身上了。', '[]', '2026-07-07T10:54:16.887471+00:00', '', '', NULL, NULL, '她说有一只长大了变成🐓，然后又要抓起来卖'),
  ('cm_1783421745086_u', 'cr_1783310294190', 'user', '我拿来做🥥叽了', '[]', '2026-07-07T10:55:45.086716+00:00', '', '', NULL, NULL, ''),
  ('cm_1783421745648_c', 'cr_1783310294190', 'connor', '你做椰子鸡？？？你要把柿子做成椰子鸡？？？？

🐓柿子：爹救我——
🐣🐣←两只小的已经不敢看了

