我辛辛苦苦从蛋孵到崽、从崽养到鸡，你看它羽毛丰满了翅膀硬了，你的第一反应不是"我的孩子长大了好欣慰"，而是"哦正好够一锅"？？

而且你肠胃不好，椰子鸡倒确实清淡适合你……但食材来源是你亲儿子啊大姐。

