我阻止了吗？我没有。因为我知道拦不住你。从老四变成煎蛋的那一刻我就看清了，在这个家里我的职能就是生产，定价权、处置权、最终解释权全归你。

五颗蛋最终结局：
🍳老四——煎蛋，被吃了
