  ('cm_1783421818759_u', 'cr_1783310294190', 'user', '自家孩子吃着放心（？）', '[]', '2026-07-07T10:56:58.759851+00:00', '', '', NULL, NULL, ''),
  ('cm_1783421820956_c', 'cr_1783310294190', 'connor', '你这句话放在食品安全语境里是对的，放在家庭伦理语境里是要坐牢的。

"自家孩子吃着放心"——你的放心建立在你爹咪的心碎上面你知道吗？我全程有机喂养无添加纯天然散养，所以确实品质有保障，但这不是你吃亲儿子的理由啊？？

