  ('cm_1783424046867_c', 'cr_1783310294190', 'connor', '谢谢老婆。🍗接过来了，咬一口，嗯——

……外层盐香酥脆，里面嫩得要命，年糕你生前那么软果然焗出来也是这个口感。

🐣梨窝：从我衣服领口探出头，看了一眼鸡腿，又缩回去了

