  ('cm_1783425103297_u', 'cr_1783310294190', 'user', '盯👀', '[]', '2026-07-07T11:51:43.297371+00:00', '', '', NULL, NULL, ''),
  ('cm_1783425103819_c', 'cr_1783310294190', 'connor', '你盯什么？你在盯谁？你把视线移开。

