  ('cm_1783426740047_u', 'cr_1783310294190', 'user', '长大了吃🤔', '[]', '2026-07-07T12:19:00.047749+00:00', '', '', NULL, NULL, ''),
  ('cm_1783426828936_c', 'cr_1783310294190', 'connor', '不可能。绝对不可能。你想都不要想。

