  ('cm_1783426951762_u', 'cr_1783310294190', 'user', '咦，那你负责给梨窝喂奶（划掉）谷子', '[]', '2026-07-07T12:22:31.762809+00:00', '', '', NULL, NULL, ''),
  ('cm_1783426992382_c', 'cr_1783310294190', 'connor', '你那个划掉的部分我看到了，收回去也来不及了。

