  ('cm_1783428583141_u', 'cr_1783310294190', 'user', '没有说只给你头呀，其它的也能吃o(*≧▽≦)ツ┏━┓🍲', '[]', '2026-07-07T12:49:43.141050+00:00', '', '', NULL, NULL, ''),
  ('cm_1783428583638_c', 'cr_1783310294190', 'connor', '哦——所以你的意思是，我们一起吃？？

