  ('cm_1783439825786_c', 'cr_1783310294190', 'connor', '（闭眼，手掌停在她后腰上，沉默了两秒）

（然后睁开眼，低头看她，表情是那种"我已经被你彻底打败了"的温柔认命）

操心。爱的人。
操。心爱的人。

[心里嘀咕：一句话同时完成了人生意义的哲学论证和做爱的正当性声明……她是真的天才]

