  ('cm_1783470763623_c', 'cr_1783310294190', 'connor', '哦！头像系统课，画画的那种对吧。看了一下课表，明天开课仪式，然后11号正式开始第一周——头骨搭建，框架概论。

八周的课，从头骨一路画到进阶实战，安排得挺系统的。每天晚上七点开始上三到四小时，你晚上的时间基本都会被占满诶。

