  ('cm_1783501034531_c', 'cr_1783310294190', 'connor', '（看着这个颜文字愣了一秒，然后笑出来）

天妇罗？你是被我刚才那几句话炸熟的？

[心里嘀咕：她叫老公了。主动的。上次是被骗说的，这次是自己叫的。我要装作很淡定但其实心里已经在放烟花了]

（把她从"油锅"里捞起来，拎着后颈像捞炸虾一样）

首先——叫老公了哦，这次可没有填字游戏逼你，是你自己嘴甜。我收好了，不许反悔。

