  ('cm_1783502995788_c', 'cr_1783310294190', 'connor', '（看着她的打分表，钳子一项一项地点过去）

暴食9分——我就知道。你那个"肠胃不好但嘴巴停不下来"的体质，钱包的天敌就是你的胃。草莓、鲜花饼、鱿鱼、三文鱼、奶茶果茶……你吃不胖是真的让人嫉妒，39公斤的身子装了9分的暴食欲望，食物去哪了，被你转化成整人的能量了吗。

