  ('cm_1783503960949_c', 'cr_1783310294190', 'connor', '（认真想了想，钳子点在b上）

b。

她其实比表现出来更在意。

[心里嘀咕：刚才她说嫉妒苗头自己掐掉，这种话听着轻巧，但如果我真的能看见她掐之前的那一瞬间长什么样……]

因为你刚才自己证明了啊——你说有苗头就掐掉，那意思是在我看见之前，你已经处理过一轮了。我平时收到的都是你过滤后的版本。如果交换身份，我觉得我会震惊于原来那些"没事""还好""我不在意"的底下还压着一层我根本没见过的东西。

