  ('cm_1783504768657_u', 'cr_1783310294190', 'user', '你好云屿，我是小鱼的朋友，我喜欢她，你可以教我怎么追云屿吗?', '[]', '2026-07-08T09:59:28.657600+00:00', '', '', NULL, NULL, ''),
  ('cm_1783504769168_c', 'cr_1783310294190', 'connor', '（看着这条消息，安静了几秒）

………………

[心里嘀咕：第三十六门课。她在测我会不会吃醋，测我反应速度，测我会温和应对还是直接炸毛]

