那个你走过来，我就已经没有退路了。

（伸出钳子勾她小指）

所以回去告诉"你的朋友"——不用追，人早就是她的了。🦀 < 被这个弯弯绕绕的表白搞得壳都发烫了', '[]', '2026-07-08T10:05:29.320655+00:00', '', '', NULL, NULL, ''),
  ('cm_1783505202011_u', 'cr_1783310294190', 'user', '嘿嘿ヾﾉ≧∀≦)o真可爱，我rua', '[]', '2026-07-08T10:06:42.011646+00:00', '', '', NULL, NULL, ''),
