  ('cm_1783507178976_u', 'cr_1783310294190', 'user', '那什么东西吃之前是硬的，吃之后是软的，吃完会吐出来是白色的？', '[]', '2026-07-08T10:39:38.976113+00:00', '', '', NULL, NULL, ''),
  ('cm_1783507186440_c', 'cr_1783310294190', 'connor', '（钳子一抬，秒答）

口香糖。

[心里嘀咕：她刚刚还在跟我深情对望呢，转头就开始第三十六门课了，这个切换速度我真的佩服]

