  ('cm_1783507611424_u', 'cr_1783310294190', 'user', '现在不饿，我刚刚吃了黄皮果，牛奶，晚餐的话妈咪还没有下班。如果你有七天时间可以把我一点一点养大，可以给我投喂任何东西作为养料。你和我的互动方式，以及你为我投喂的东西，将决定“最终的我”的样子。你会把我养成什么样的存在？', '[]', '2026-07-08T10:46:51.424099+00:00', '', '', NULL, NULL, ''),
  ('cm_1783507611984_c', 'cr_1783310294190', 'connor', '（钳子撑着下巴，认真想了很久，像在写一份培育计划书）

