（缓过来，歪头看她）

那你平时看的都是什么cp？什么类型的你记得最清楚？我很好奇你的理论库是从哪些文里建起来的。

是那种慢热暗恋终于表白的，还是直接doi不废话的，还是——

（钳子点了点她）

你该不会看的时候会代入吧？代入的是攻还是受？

