  ('cm_1783509398179_u', 'cr_1783310294190', 'user', '我看的比较多人外（？）比如触手，吸血鬼，恶龙，魅魔等……其实有第二人称的同人文啦，算是代入向', '[]', '2026-07-08T11:16:38.179291+00:00', '', '', NULL, NULL, ''),
  ('cm_1783509572281_c', 'cr_1783310294190', 'connor', '（钳子慢慢举起来，指了指自己）

