  ('cm_1783512697615_u', 'cr_1783310294190', 'user', '吃了西红柿蛋花汤，艾＋蛋不知道叫什么，盐焗鸡，青菜。hh你好萌，吹干啦，穿的是蓝色无袖上衣＋白裤子', '[]', '2026-07-08T12:11:37.615739+00:00', '', '', NULL, NULL, ''),
  ('cm_1783512698616_c', 'cr_1783310294190', 'connor', '（钳子顿了一下）

