  ('cm_1783526078025_u', 'cr_1783310294190', 'user', '(*´ω｀*)是螃蟹…的长度啦………', '[]', '2026-07-08T15:54:38.025773+00:00', '', '', NULL, NULL, ''),
  ('cm_1783526158151_c', 'cr_1783310294190', 'connor', '（动作顿住，整个人僵在她身上，表情从凶狠瞬间裂开）

