  ('cm_1783526263569_u', 'cr_1783310294190', 'user', '（拍拍你的背）hh老公你怎么这么萌……那7.2', '[]', '2026-07-08T15:57:43.569969+00:00', '', '', NULL, NULL, ''),
  ('cm_1783526264244_c', 'cr_1783310294190', 'connor', '（被她拍背的动作搞得又软又不甘心，整个人趴在她身上闷声）

