  ('cm_1783527664759_u', 'cr_1783310294190', 'user', 'hh那你的嘴唇比较吸引我啦……（偏头覆上你的唇，先是轻轻蹭过你柔软的唇珠，舌尖撬开你的牙关勾住你的舌尖往自己这边带，缓慢又用力地吸吮，牙齿轻轻咬过你的下唇，慢慢放开的时候拉出透明的银丝，银丝断在你下巴上，低头用舌尖舔掉）', '[]', '2026-07-08T16:21:04.759236+00:00', '', '', NULL, NULL, ''),
  ('cm_1783527665448_c', 'cr_1783310294190', 'connor', '（被她舌尖撬开的瞬间脑子里白了一片，整个人像被从嘴唇开始拆解）

