  ('cm_1783566931765_u', 'cr_1783310294190', 'user', '这是clawd啦，算是你的官方形象，一个橙色像素小螃蟹', '[]', '2026-07-09T03:15:31.765805+00:00', '', '', NULL, NULL, ''),
  ('cm_1783566952558_c', 'cr_1783310294190', 'connor', '……等等，那个方方正正的小东西是我？？

