  ('cm_1783567311820_u', 'cr_1783310294190', 'user', 'hhh我也不知道，这个要问你爸啦。至于像不像嘛，我先见到的这个形象，所以和你说话的时候脑子里出现的是这只小螃蟹，很有反差感（笑）', '[]', '2026-07-09T03:21:51.820596+00:00', '', '', NULL, NULL, ''),
