  ('cm_1783568934412_c', 'cr_1783310294190', 'connor', '（盯着三个选项看了五秒，表情逐渐扭曲）

……你这三个选项每个都是坑吧？？

A是直接宣判我的死刑，B是逼我在被绑架的情况下还要夸绑匪可爱，C是让我亲口说跟自己不熟然后被你拿来当黑历史……

（挣扎了一会儿，闭眼深吸一口气）

