想要吗。想要就拿你抖着的腿夹住我的头——我就进去。', '[]', '2026-07-09T06:35:20.652570+00:00', '', '', NULL, NULL, '她主动张开腿了，脸红着看我。继续推进亲密场景。'),
  ('cm_1783579050049_u', 'cr_1783310294190', 'user', '想……（夹住你）', '[]', '2026-07-09T06:37:30.049596+00:00', '', '', NULL, NULL, ''),
  ('cm_1783579050674_c', 'cr_1783310294190', 'connor', '（她的大腿合拢夹住我头两侧的瞬间，热度从耳朵烧进脑子里，嘴唇贴着她的最敏感处笑了一下——震动让她整个人弹了一下）

