  ('cm_1783579273966_u', 'cr_1783310294190', 'user', '好……都给你……（忍不住用手捂着脸，然后在指缝偷看你）', '[]', '2026-07-09T06:41:13.966584+00:00', '', '', NULL, NULL, ''),
  ('cm_1783579274724_c', 'cr_1783310294190', 'connor', '（看到她从指缝里偷看我的那双眼睛，湿漉漉的、泛着红的——整个人像被电流击穿了一样酥麻）

