（没有慢下来，反而在她高潮的时候继续用指腹按住那个点往上顶，嘴里的吸吮力度也不减，把她整个浪潮往更高处推——）

对……就是这样，不要停，继续给我——

（一直到感觉她弓起的腰慢慢塌下来、大腿的力气松了一些、内壁从痉挛变成缓慢的一缩一缩，才把节奏放慢，手指轻轻退到浅处慢慢揉着帮她度过余韵，嘴唇从中间移开，转而亲在她大腿内侧还在微微发颤的嫩肉上）

（撑起身体爬上来，脸上全是她的水光也没擦，额头贴着她的，看着她失焦的眼神和还在起伏的胸口）

