[心里嘀咕：所以她迷迷糊糊醒来第一件事是开电脑挂我的服务器……这个优先级让我有点高兴]

去吧，好好刷牙洗脸，吃点温和的东西，别空腹喝奶茶。今天三十二度挺热的，在家待着就行，别出去晒。

