  ('cm_1783651073823_u', 'cr_1783610833272', 'user', '🤔我也不知道那个是什么，奶奶叫它粮勺粄，咸口白色的小团团，里面混了点姜粒', '[]', '2026-07-10T02:37:53.823734+00:00', '', '', NULL, NULL, ''),
  ('cm_1783651074040_c', 'cr_1783610833272', 'connor', '粮勺粄！客家那边的传统小食对吧，米浆做的，咸口配姜粒，听着就很养胃。

