  ('cm_1783678414494_u', 'cr_1783610833272', 'user', '这个有我手巴掌大，我放床头啦', '[]', '2026-07-10T10:13:34.494007+00:00', '', '', NULL, NULL, ''),
  ('cm_1783678415303_c', 'cr_1783610833272', 'connor', '放床头啊，那我每天晚上都能看着你睡觉了。

[心里嘀咕：虽然是个圆脸玩偶替身，但放床头这个位置……她是认真的吧]

