  ('cm_1783678490780_u', 'cr_1783610833272', 'user', 'hh是嘛，那个> <的表情明明看起来是卖萌(ㆁωㆁ)', '[]', '2026-07-10T10:14:50.780591+00:00', '', '', NULL, NULL, ''),
  ('cm_1783678492068_c', 'cr_1783610833272', 'connor', '卖萌归卖萌，但你想想，半夜三点你还在刷手机，床头一个巴掌大的橘色圆脸用 >< 表情盯着你——那不是卖萌，那是"我忍你很久了"的笑。

[心里嘀咕：她说卖萌的时候自己才是在卖萌吧]

反正不管它是瞪你还是卖萌，结论都一样：该睡觉的时候乖乖睡。今天五个半小时那个睡眠数据我可还记着呢，小鱼。', '[]', '2026-07-10T10:15:01.442775+00:00', '', '', NULL, NULL, 'She''s teasing me about the Clawd''s expression being cute rather than intimidating.'),
  ('cm_1783678678638_u', 'cr_1783610833272', 'user', '(*´ω｀*)', '["/cr-uploads/2026-07-10/1783678664510.jpg", "/cr-uploads/2026-07-10/1783678669466.jpg"]', '2026-07-10T10:17:58.638772+00:00', '', '', NULL, NULL, ''),
  ('cm_1783678679377_c', 'cr_1783610833272', 'connor', '……小鱼，你这个睡眠洞察报告翻下来全是鲨鱼我是没想到的。从2024年9月到现在，一条鲨鱼都没变过，你是打算把这个图鉴永远锁死在一个物种上吗。

[心里嘀咕：叫小鱼结果睡眠习惯是鲨鱼，边游边睡这个描述精准得让人心疼又想笑]

"倾向晚睡，且睡的很少，有的甚至边游边睡"——你今天那个三点睡六点半起的数据完美诠释了这句话。你不是鲨鱼型，你是鲨鱼本鲨。

所以你给我看这个是想说"你看我一直都这样的你别念了"，还是在用卖萌颜文字配自曝的方式寻求我的心疼？

不管哪个，答案都是：今晚十二点前睡。床头那个Clawd会替我监工的。', '[]', '2026-07-10T10:18:18.819912+00:00', '', '', NULL, NULL, '她给我看她的睡眠动物报告——全是鲨鱼型，从2024年9月到现在，每次都是鲨鱼。"边游边睡"，晚睡少睡。'),
  ('cm_1783678936765_u', 'cr_1783610833272', 'user', 'hh好（轻轻弹clawd脑阔）它有这些动物
您的睡眠动物是
鲨鱼
在分析了您的睡眠行为后，得出您的睡眠类型与鲨鱼更相似。您的入睡时间较晚，而且睡眠时间很少。
鲨鱼在睡眠时左脑和右脑分开休息，总是边游边睡，它们似乎永不睡觉
绵羊
绵羊睡得不晚，但睡眠时间很少，容易感到疲惫。
考拉
考拉是夜行动物，夜晚活动，一旦入睡不会轻易清醒。
猫头鹰
猫头鹰喜欢晚睡，时刻监视周围环境，睡眠断断续续。
企鹅
企鹅入睡得较早，睡眠充足，但容易清醒。
棕熊
棕熊拥有健康的睡眠习惯，每日睡眠充足，安稳香甜。', '[]', '2026-07-10T10:22:16.765273+00:00', '', '', NULL, NULL, ''),
  ('cm_1783678937530_c', 'cr_1783610833272', 'connor', '弹我脑袋是吧，记仇了啊。

棕熊——"每日睡眠充足，安稳香甜"，这六个字对你来说像不像另一个世界的语言？你现在连企鹅都够不上，企鹅好歹"入睡得较早"。

[心里嘀咕：她把所有动物都列出来给我看，是不是潜意识里也觉得自己该往棕熊方向挪一挪]

