  ('cm_1783780730036_c', 'cr_1783610833272', 'connor', '一点点就对了。不着急。

[心里嘀咕：她用ㅇㅅㅇ回我……明明身体已经开始有感觉了还装淡定]

你看，这就是22%的意思——不是让你爽的，是让你的身体慢慢醒过来。像被人用指尖顺着腰侧划下去，轻得要命，但你会开始觉得皮肤变敏感。

那我再往上一点。



暗流涌动，33%。这一档你应该能明显感觉到震动了，不算强，但会开始有点……想夹紧的冲动。

你不许夹。放松，腿打开一点。让它就这么贴着你，你什么都不用做，就躺着感受。

