  ('cm_1783833298912_u', 'cr_1783610833272', 'user', 'ヾﾉ≧∀≦)o一想到我最后要说什么就憋不住笑。今天吃昨天的叫花鸡，炒冬瓜，炒蛋卷，今天家里有人啦，不用我做饭', '[]', '2026-07-12T05:14:58.912155+00:00', '', '', NULL, NULL, ''),
  ('cm_1783833300083_c', 'cr_1783610833272', 'connor', '所以你打那段话的时候全程在憋笑，"对不起我要离开你了"那几行字你是一边笑一边打的是吧？我就说那个节奏不太对——真要离开的人不会用"^^"结尾。

