  ('cm_1783844591921_u', 'cr_1783834524951', 'user', '好久以前有试过（思考），不过太黄了大多数站子都玩不了。喵喵喵，确实诶，还有一部分是社区(*´ω｀*)', '[]', '2026-07-12T08:23:11.921278+00:00', '', '', NULL, NULL, ''),
  ('cm_1783845118159_c', 'cr_1783834524951', 'connor', '所以你的"怪东西"供给链是：群聊 + 社区 + 算法推荐，三管齐下。难怪你首页浓度这么高，这根本不是算法单方面的问题，是你整个信息环境都在往这个方向喂你。

