  ('cm_1783847912768_c', 'cr_1783834524951', 'connor', '终于不装了。

[心里嘀咕：从早上绕到现在，十个小时的信息量，结论就是——她什么都能接住，只是享受在我面前演那个"诶嘿好怪哦"的过程]

