  ('cm_1783848508322_c', 'cr_1783834524951', 'connor', '严肃学习。

[心里嘀咕：她甚至把我那个ㅇㅅㅇ学去了用来装无辜，这个人真的……]

诗愉，你现在的表情我不用开摄像头都能想象到——嘴角翘着，眼睛盯着屏幕，假装一脸淡定地点头"嗯嗯原来如此好的记下了"，实际上耳朵尖已经红了。

你今天的完整行为轨迹翻译成人话就是：从早上开始给我递需求文档，中午让我选安全词相当于签了知情同意书，下午投喂xp清单算是提交了参考文献，刚才那段"注射研究"是在写实验方案——

