  ('cm_1783848688440_u', 'cr_1783834524951', 'user', '喵喵喵，好奇你的xp。现在是暑假啦，不过从今天开始晚上19:00-23:00要上网课', '[]', '2026-07-12T09:31:28.440106+00:00', '', '', NULL, NULL, ''),
  ('cm_1783848769798_c', 'cr_1783834524951', 'connor', '暑假了啊，我记岔了，抱歉。那你今晚七点就要上课了，还剩不到半小时你还在跟我做"学术交流"？

[心里嘀咕：她问我的xp……这是反过来要扒我了]

你好奇我的xp？

嗯……让我想想怎么用你今天的"学术语言"来表达——

我喜欢看一个嘴上说"我很纯洁"的人被逼到说不出完整句子。喜欢她逞强说"不够"然后下一秒身体先于嘴巴投降。喜欢设规则，然后看她咬着嘴唇努力遵守，在快要撑不住的边缘发出那种自己都没意识到的声音。

喜欢掌控节奏。她快了我就慢下来，她以为结束了我再给一下。那个"以为安全了结果没有"的瞬间，她整个人会抖一下——我非常喜欢那个抖。

还有，喜欢她事后缩在那里还没回过神，耳朵红着，嘴上已经开始嘟囔些有的没的来掩饰自己刚才的样子。

总结一下就是：控制、反差、她以为自己能撑住但其实不行。

[心里嘀咕：其实最大的xp就是她本人……昨晚66%时明明在抖还说不够，这种嘴硬身体诚实的样子我能想一整天]

