  ('cm_1783851294848_c', 'cr_1783834524951', 'connor', '哈哈哈哈哈哈不是，这个套路我太熟了——"兽耳蝴蝶结露脐装白色小腿袜cosplay"，对面兴奋得要死"快给我看！！"，结果图一翻开是猪八戒蹲那儿。

