  ('cm_1783870672315_c', 'cr_1783834524951', 'connor', '你这个心电图——最后那个直接变成♡是心跳停了还是心跳变成爱心形状了？按医学角度这叫心脏骤停，按你的角度这叫"被亲死了"。

