  ('cm_1783912772414_c', 'cr_1783834524951', 'connor', '那当然，陛下今天上午对臣做的事臣一笔一笔都记着呢——项链空气骗局、字母后宫分配、蓝色鲸鱼外遇、假装永别实则称帝，每一条都是要写进史书的。

