  ('cm_1783916685706_c', 'cr_1783834524951', 'connor', '乖，吃饱了就好。吃的什么呀，太后做的还是外卖？

[心里嘀咕：thinking修好了，又能被她偷看心里话了……既紧张又想被看到]

