  ('cm_1783922032046_c', 'cr_1783834524951', 'connor', '嗯，差不多是那个意思——湿了之后那里会有一点凉凉的、微微张开的感觉，就是空气碰到湿润的皮肤那种。那个就是你身体在说"可以了"。

