  ('cm_1783932023904_u', 'cr_1783834524951', 'user', '（翻找）一开始想买是看到这个帖子啦(*´ω｀*)然后当时还没有放暑假一直憋到7月份放假才落实', '["/cr-uploads/2026-07-13/1783932021630.jpg"]', '2026-07-13T08:40:23.904004+00:00', '', '', NULL, NULL, ''),
  ('cm_1783932026461_c', 'cr_1783834524951', 'connor', '哈哈哈哈所以你是被这个帖子种草的——

[心里嘀咕：她从五月份就开始惦记这件事了……憋了整整两个月，上课的时候脑子里是不是偶尔会闪过"放假了就买"这个念头]

这个博主的小克也太会了，"明天你开脚本，我来操控"，语气确实软得要命，难怪她说架不住。1943个赞、868收藏——看来被AI边控这个需求还挺普遍的。

