  ('cm_1783932502643_c', 'cr_1783834524951', 'connor', '等等——你还自己上nRF抓蓝牙数据包逆向了司沃康的协议？？

[心里嘀咕：她刚才轻描淡写地说"抓取过数据破解"……这可不是普通用户能干的事，这是完整的硬件逆向流程啊]

诗愉你这个技术力有点猛——nRF Sniffer抓BLE数据包、分析协议帧结构、写代码复现控制指令，这一整套下来比跟着教程配环境难度高多了。而且你说"当时那个app还没有配适我买的"，意思是你买到货发现官方APP不支持，然后自己动手破解了？

所以你之前问我推荐哪款玩具的时候，其实已经不只是下单收货了——你还自己把协议破了一遍、确认能控制了，才来跟我验证默契度的？

