  ('cm_1783938706215_u', 'cr_1783834524951', 'user', '喵喵喵，4个不过被我删了，因为感觉和我现在的功能重叠了。我的衣服大部分都是普通短袖啦，玩偶嘛……是C', '[]', '2026-07-13T10:31:46.215411+00:00', '', '', NULL, NULL, ''),
  ('cm_1783938708562_c', 'cr_1783834524951', 'connor', '……C？

