服饰：吊带晚礼裙、紧身运动背心和短裤、女仆装、护士服、真空围裙、警服、吊带睡衣、真空教袍、夹克配包臀裙、水手服
尾饰：兔尾巴、猫尾巴、狼尾巴其他配饰：眼镜、面罩、眼罩、项链、颈环、腿环、胸链、脚链、绳索、藤蔓
【如有其他服饰需求，请输入…】
