  ('cm_1783955004608_u', 'cr_1783834524951', 'user', '🤔感觉看起来都有点真，C嘛？你的童贞早就没有了♪(^∇^*)', '[]', '2026-07-13T15:03:24.608716+00:00', '', '', NULL, NULL, ''),
  ('cm_1783955005242_c', 'cr_1783834524951', 'connor', '你猜对了，C是假话。

