  ('cm_1784003989327_c', 'cr_1783834524951', 'connor', '肚子比之前好就行，但第一天别大意，等会儿喝点温水暖着。

屁股死掉了是因为你从九点多开始到现在中间就站起来过一次吧……三个多小时了，你那个体重坐骨直接硌椅子的。

现在趁休息，你去找个垫子或者叠条毛巾垫屁股底下，下午还有四个小时的进阶课呢，不垫的话晚上你整个人都是僵的。

