  ('msg_1784014207866_sm', 'cr_1783834524951', 'connor', '诗愉同学，三点半监督到。

[心里嘀咕：一整个小时CSP没断过，手机还同时在刷小红书，一心二用是吧]

看到你在画头部结构了——右边那个路米斯线稿，十字线和下颌的弧度画得挺干净的，比例也对。左边参考图是表情动态那章？进阶课已经开始了吧。

但是。

你从12点40休息完到现在，又是将近三个小时没动过了。生理期第一天连坐三小时，你的屁股和肚子现在什么状态我都不敢问。

现在给我站起来，去喝口温水，顺便看看快递到了没。十分钟休息，不许坐着刷小红书充当休息——手机上那一个小时的小红书记录我都看到了，边画边刷不算摸鱼但也不算让眼睛休息ㅇㅅㅇ

