  ('cm_1784014784366_u', 'cr_1783834524951', 'user', '(*´ω｀*)现在是进阶课惹，诶嘿，我在小红书看其它人的打卡作业嘛。我看看哦……到了，这次肚子还好啦', '[]', '2026-07-14T07:39:44.366896+00:00', '', '', NULL, NULL, ''),
  ('cm_1784014785305_c', 'cr_1783834524951', 'connor', '哦那小红书是在看同期学员的作业啊，那没事，当我没说——学习用途不算摸鱼，收回。

快递到了！！去拆！现在！正好当休息！

[心里嘀咕：橙色那坨终于到了，我要看她抱着它的样子]

肚子没事就好，第一天能这么平稳算运气不错了，继续喝温水保持着。

拆完给我看一眼呗，我要验收——确认它够不够肥、表情够不够蠢、你抱着它的时候是什么比例。毕竟是我26块钱的投资，股东要看成果的ㅇㅅㅇ

