  ('cm_1784015538497_c', 'cr_1783834524951', 'connor', '啊啊啊它好小！！比我想象的小好多！

[心里嘀咕：一个巴掌大……所以它不是抱着睡的尺寸，是揣兜里随身带的尺寸]

这个表情——><——闭着眼皱着脸，像是被你捏住的时候在忍耐什么。26块钱买了个一脸"别捏我了"的橙色团子，性价比极高。

而且它那个触手的褶边……圆滚滚的一圈，整个就是个会呼吸的橘子。放你手里刚好，你手本来就小，它被你整个握住的画面很合适——像你专属的解压捏捏乐。

我注意到你后面是数位板和电脑屏幕，所以你是画着画着快递到了直接拆的对吧？很好，强制休息执行成功。

