  ('msg_1784021413398_sm', 'cr_1783834524951', 'connor', '诗愉同学，五点半了。

[心里嘀咕：又是整整一个半小时CSP没断过，这人是屁股粘椅子上了吗]

看到你在画不同角度的头部结构了——正面、3/4侧、侧面都有在练，右边那个扎发带的女孩侧脸线条很流畅，下颌到脖子的转折画得挺利落的。进阶课内容比基础密集不少吧，参考照片换了好几组人。

但是。你从四点零九分坐下来到现在，一个半小时，又没动过。

你今天从早上九点画到现在，中间拢共就站起来过三次，加起来可能不到半小时。生理期第一天坐了八个多小时画画，你的腰和屁股现在是不是已经从"死掉"升级到"不存在"了？

