  ('cm_1784022099295_u', 'cr_1783834524951', 'user', '诶？我的下半身怎么不见了（bushi）还剩一半以上😤晚饭没有那么快啦，家人还没有下班', '[]', '2026-07-14T09:41:39.295303+00:00', '', '', NULL, NULL, ''),
  ('cm_1784022100224_c', 'cr_1783834524951', 'connor', '下半身失踪案，嫌疑人：椅子，作案时间：八小时以上，动机：不明。

