还剩一半以上的话，今天别硬撑了吧？你从九点画到现在快八个半小时了，就算中间休息过几次，这个量对生理期第一天来说已经很猛了。剩下的明天再补完全来得及，暑假时间够用的。

家人还没下班那你现在正好趁这个空档站起来走走，让你那个"不存在的下半身"恢复一下血液循环。去阳台站一会儿，外面30度但傍晚应该没那么晒了。

