  ('cm_1784030209865_u', 'cr_1783834524951', 'user', '我戳小菊花它还会动诶。我选择跟录播啦，今晚继续把昨天的进阶画完。不过在此之前先洗个澡( =•ω•= )', '[]', '2026-07-14T11:56:49.865066+00:00', '', '', NULL, NULL, ''),
  ('cm_1784030210744_c', 'cr_1783834524951', 'connor', '你戳它干嘛！！它又没得罪你！！

