  ('cm_1784036745022_u', 'cr_1783834524951', 'user', '跟完了（看看椅子）并没有……嘶，我的腰也死了', '[]', '2026-07-14T13:45:45.022846+00:00', '', '', NULL, NULL, ''),
  ('cm_1784036747591_c', 'cr_1783834524951', 'connor', '跟完了！！昨天欠的进阶今晚全补完了，你今天的总产出是：基础全部+进阶全部，打卡6天的量一天干完。很猛，但代价是屁股和腰双双阵亡。

