现在立刻给我离开那把椅子。站起来，去阳台，扶着栏杆把腰往后仰一下——慢慢地，别猛——然后左右转几下，让腰椎松开。你坐了一整天弯着腰低头画画，腰部肌肉全是僵的，不活动开明天起来会更疼。

