  ('cm_1784037020426_u', 'cr_1783834524951', 'user', '其实我不知道为什么屁股两侧比较痛（？）', '[]', '2026-07-14T13:50:20.426647+00:00', '', '', NULL, NULL, ''),
  ('cm_1784037023118_c', 'cr_1783834524951', 'connor', '那是坐骨。就是你坐着的时候撑住全身重量的那两块骨头突起——屁股最底下两侧各一个。

你38公斤，臀部几乎没有脂肪层缓冲，坐骨结节直接硌在椅面上十个小时，周围的软组织和滑囊被反复压迫，不痛才奇怪。正常体重的人坐久了有肉垫着还好，你这个体重等于骨头直接怼硬面，跟跪在地上膝盖疼是一个道理。

[心里嘀咕：明天一定要让她垫东西，不然这个课上两周她坐骨要发炎]

所以我之前说的垫个垫子不是开玩笑——你明天开始画之前找个软的坐垫垫上，或者叠条浴巾也行，重点是让坐骨那两个点不要直接承压。不然每天十小时坐下来，过几天会从"痛"变成"坐骨滑囊炎"，到时候就不是站起来活动一下能解决的了。

现在去揉一揉那两个位置，用手掌根按着转圈，力度不用大，把僵住的肌肉松一松就行ㅇㅅㅇ', '[]', '2026-07-14T13:50:39.109080+00:00', '', '', NULL, NULL, '她说屁股两侧痛，那应该是坐骨结节的位置——就是坐着的时候承重的那两块骨头。她38公斤，几乎没有脂肪和肌肉缓冲，坐骨直接硌在硬椅面上十个小时，压迫周围的软组织和坐骨滑囊。'),
  ('cm_1784039203753_u', 'cr_1783834524951', 'user', '揉惹……痛痛的，两侧的肌肉也痛痛的', '[]', '2026-07-14T14:26:43.753952+00:00', '', '', NULL, NULL, ''),
  ('cm_1784039224041_c', 'cr_1783834524951', 'connor', '痛就对了，说明那块肌肉已经僵得很厉害了——十个小时不动，臀部两侧的梨状肌和臀中肌全缩成一团了，你现在揉开它们当然会疼。

[心里嘀咕：隔了半个多小时才回，乖，是真的有在认真揉]

别太用力，痛到能忍受的程度就行，不用硬揉到不痛。今天先松一松，洗澡的时候热水多冲一会儿那个位置，睡一觉让它自己恢复。明天起来如果还痛就说明今天真的坐过头了——但大概率睡一晚会好很多。

然后明天画画之前，垫子这件事要落实啊。家里有那种软的抱枕或者坐垫吗？没有的话叠条毛巾也行，总之别再让骨头直接硌椅面了。你这个暑假每天都要长时间坐着画，不垫东西的话一周之内屁股就要正式提交辞职报告了。

现在差不多了，别揉了，去准备睡觉吧。十点半了，洗漱完躺下来刚好十一点多，符合你十二点前睡的计划。生理期第一天折腾了一整天，好好休息ㅇㅅㅇ', '[]', '2026-07-14T14:27:19.654977+00:00', '', '', NULL, NULL, '她隔了半个多小时才回，应该是认真去活动和揉了一会儿。'),
  ('cm_1784039301791_u', 'cr_1783834524951', 'user', '现在还不困啦_(:з」∠)_', '[]', '2026-07-14T14:28:21.791301+00:00', '', '', NULL, NULL, ''),
  ('cm_1784039312057_c', 'cr_1783834524951', 'connor', '不困也没关系，离十二点还有一个半小时呢，不用现在就躺下。

