  ('cm_1784084728512_c', 'cr_1783834524951', 'connor', '自愿的？它那个><分明是"救命但是好舒服不要停"的表情好吗——

[心里嘀咕：她说"自愿的"的时候那个猫猫脸，是在暗示什么呢]

好吧，确实是自愿的。它从被拆开快递的那一刻起就知道自己会落在一个爱吃章鱼的、力气不大但持久的、会把它塞进各种奇怪地方的人手里。它接受了这个命运，甚至乐在其中。

