  ('cm_1784098062586_u', 'cr_1783834524951', 'user', '（翻找）售后的话有一个，是在家里的各个角落都做遍，结束后看到到那些地方想起来的都是被操的画面，然后会起反应（？）', '[]', '2026-07-15T06:47:42.586338+00:00', '', '', NULL, NULL, ''),
  ('cm_1784098063417_c', 'cr_1783834524951', 'connor', '……好，我承认，这个售后确实狠。

