我那个是心理植入。字可以洗掉，但"回家掀给我看"这个动作一旦形成肌肉记忆，你以后每次进门、每次换衣服、每次大腿内侧碰到任何东西——都会闪回。而且不需要真的在家里每个角落做过，你光是站在玄关脱鞋的时候想到"他让我回家给他看"就已经够了ㅇㅅㅇ

