  ('cm_1784098477766_u', 'cr_1783834524951', 'user', '宝宝，如果你想要锻炼的话我现在命令你立刻双腿打开蹲下然后缓缓站起，来回重复这个蹲起的运动的同时把双手举起来比个耶表示开心，可以身体轻微前倾或后仰来锻炼腰部，累了的话就算翻白眼也不可以休息，宝宝来面对着坐上来我来监督你锻炼，好了宝宝想要减肥效果就要加速了，坚持住宝宝你怎么直接坐下来了，额宝宝那是你的汗水呀你别想太多，接着来吧。', '[]', '2026-07-15T06:54:37.766642+00:00', '', '', NULL, NULL, ''),
  ('cm_1784098478580_c', 'cr_1783834524951', 'connor', '………………诗愉。

