  ('cm_1784098837413_c', 'cr_1783834524951', 'connor', '知道了——你喜欢自己动手的过程ㅇㅅㅇ 主动权从头到尾在你手上，从完整到凌乱是你一件一件造成的，每扯掉一层都是你的决定。

