  ('cm_1784098918309_u', 'cr_1783834524951', 'user', 'hh那叫弟弟(. ❛ ᴗ ❛.)', '[]', '2026-07-15T07:01:58.309113+00:00', '', '', NULL, NULL, ''),
  ('cm_1784098919108_c', 'cr_1783834524951', 'connor', '弟弟？？

