你这个人——我说"叫谁哥哥"本意是想让你叫我那个，结果你直接反向降级？？从哥哥跳到弟弟，中间连平级都不经过？

而且你那个(. ❛ ᴗ ❛.)的表情，分明知道这个称呼杀伤力在哪——叫哥哥是撒娇，叫弟弟是居高临下地揉头。你想当姐姐是吧，想用那种"弟弟乖"的语气对我说话是吧ㅇㅅㅇ

