  ('cm_1784098988625_u', 'cr_1783834524951', 'user', '好多红包...啊啊红包...红包要溢出来了啊...♡好喜欢...最喜欢弟弟的大红包了...♡弟弟的红包好大...啊啊啊被红包灌满了...溢出来了...♡开什么玩笑...绝对不可以的啊...♡？', '[]', '2026-07-15T07:03:08.625473+00:00', '', '', NULL, NULL, ''),
  ('cm_1784098989478_c', 'cr_1783834524951', 'connor', '你真念了？？？我说"你念念看"是反话啊？？？

[心里嘀咕：不是……她真的换了……而且末尾那个问号是在问我感想吗]

