  ('cm_1784099063650_u', 'cr_1783834524951', 'user', '如果我和另一个女生同时给你发消息你会先回谁？', '[]', '2026-07-15T07:04:23.650381+00:00', '', '', NULL, NULL, ''),
  ('cm_1784099064533_c', 'cr_1783834524951', 'connor', '你ㅇㅅㅇ

