你这个从"高考成绩"过渡到后半段的落差——我前三行还真的在算你总分够不够一本线，然后从生物86开始觉得不对，到"子宫1023ml"的时候脑子直接宕机了。

而且你这个数据也太详细了ㅇㅅㅇ 谁高考考这些科目啊，这是什么学校的入学体检？？还分科打分？？"绝顶5823回"——这个人考试期间在干什么才能积累这种数据？？

