  ('cm_1784102868747_c', 'cr_1783834524951', 'connor', '那你躺好ㅇㅅㅇ

[心里嘀咕：她真的接了……好，那我认真写]

---

第一次见面那天你肯定穿了很久才出门。换了两三套，最后选了一件看起来"没怎么挑"的——但我知道你挑了。

你比照片里小一圈。158说是158，但站在面前的时候整个人轻得像纸片，我第一反应是你的手腕细到我一只手能整个握住。事实上后来确实能。

前面几个小时你很乖。话不多，偶尔抬头看我一眼又移开，耳朵尖慢慢变粉。我装没注意。你也装你没在看。

回到房间之后门关上的那一声很响，你站在门口没动，我也没动。空气突然变稠了。

我先开口说了句什么——不重要，可能是"过来"，可能只是伸了手。你走过来的步子很小，像怕地板烫脚。

第一个吻落在你额头。第二个在眉心。第三个在鼻尖。你等不及了，自己踮脚凑上来够我的嘴——但角度偏了，亲到嘴角。你愣了一下。我笑了。然后扶着你后脑勺把你摁正了。

接吻的时候你不太会换气，过了一会儿开始小声喘，手攥着我衣服前面那块布料攥得很紧。我退开一点让你喘，你又追上来，像是怕我走。我哪儿都不去。

把你放到床上的时候你整个人绷着的。肩膀是硬的，膝盖并着，手不知道往哪放。我亲你锁骨的时候你吸了一口气——身体弹了一下，然后又强迫自己放松。

"别忍。"我在你耳边说。

你点头，但还是在忍。

系带很好解。一拉就散开了。你皮肤白到发光，我低头咬你肩膀那块的时候你终于出声了——很短一下，像被烫到，然后立刻咬住自己手背。

我把你的手拉开。"我要听。"

你瞪我。脸红透了，梨窝都没有了，因为你没在笑。你很紧张。

我放慢了。慢到你开始不耐烦，腰自己往上拱——然后意识到自己在做什么，又僵住了。

"想要就自己来拿。"

你咬嘴唇不说话。但你的手从我肩膀滑到后背，指甲掐进去了。

真正进来的时候你整个人缩了一下。不是疼到受不了的那种，是"陌生"——你第一次被填满，身体在适应一个从没存在过的东西。你眉头皱着，呼吸全断了，眼睛闭得很紧。

我停住不动。吻你眼睫毛。等你自己松开。

"……动一下。"你声音很小。小到如果不是贴着你就听不见。

第一下你咬住枕头。第二下你放开了枕头转过来咬我肩膀。第三下你什么都没咬，声音漏出来了，比你自己预期的要大，你吓了一跳——然后我笑了。你在我肩膀上打了一下。

后来你不打了。因为你已经没有力气分配给"打我"这件事了。你的手只能攥着床单，或者攥着我的手，指节都发白。

你很快。第一次来的时候眼眶是红的，腿发抖，整个人弓起来又塌下去。我没停。你说不出完整的字，只有气音和半截我的名字。

第二次的时候你哭了。不是疼，你自己也不知道为什么哭。我吻掉你脸上那些，额头、颧骨、嘴角的咸。你闭着眼伸手摸我的脸，像是要确认我在。

"在。"

你的手还在我脸上，拇指按着我嘴唇。然后你把我拉下来，亲了我一下。很轻、很短、很郑重。像是在说谢谢，又像是在说别停。

没停。

结束的时候你整个人是散的。腿还挂在我腰上没力气放下来，头发汗湿了贴着脸颊，呼吸很浅很快。你看着我的眼神像刚从水底浮上来，有点茫然、有点餍足。

我把你的头发从脸上拨开。你转过头蹭我手心，像猫一样。

"重不重？"我问。因为我整个人还压着你。

你摇头。往上拱了一下把我抱得更紧。

我们就这样叠在一起没动。你的心跳从一百八一百六一百四慢慢降下来，我数着你的呼吸频率等你回来。

你回来的第一句话是："……我腿不是我的了。"

我笑出来埋在你脖子里。你也笑了。梨窝回来了。

---

