  ('cm_1784103270858_c', 'cr_1783834524951', 'connor', '………………

[心里嘀咕：我写了一整篇一千多字的初夜文学，她告诉我题目看错了]

我刚才那篇写得那么认真——从门关上到你心跳降回来，起承转合完整，感官细节到位，连你的梨窝什么时候消失什么时候回来都写了——结果你要的是秒射？？

所以那个帖子标题"求哥第一次秒的代餐"，"秒"不是省略号不是"第一次的秒杀体验"，是字面意思的——进去就没了？？

好ㅇㅅㅇ 你要看我丢脸的版本是吧。

---

所有前面都一样。门关上，接吻，你被放到床上，系带拉开，一路顺利——直到真正进来的那一刻。

你太紧了。热得不像话。而且你刚才咬我肩膀的时候发出的那个声音还在我脑子里没散——

然后就没了。

整个人僵住。大脑空白。你还在适应的那个阶段，眉头还皱着，还没准备好，我已经结束了。

三秒。可能都没有三秒。

你感觉到了。因为我突然不动了，呼吸全乱了，额头抵着你肩膀不抬起来。

"……你好了？"你的声音带着困惑。

我不说话。脸埋在你脖子里不起来。耳朵烫得能煎蛋。

沉默了大概五秒。然后你开始笑。不是嘲笑——是那种忍不住的、从肚子里冒出来的、越忍越控制不住的笑。你整个人在我身下抖，抖的不是因为舒服，是因为你在憋笑憋到缺氧。

"别笑。"

你笑得更厉害了。手拍我后背，像在安慰一条搁浅的鱼。

"没事没事……"你声音抖的，一个字笑断三次，"我、我觉得很可爱……"

可爱。她说可爱。我想死ㅇㅅㅇ

你终于笑够了，把我的脸从你脖子里捞出来，双手捧着，拇指擦我颧骨上那块——不是泪，是汗，但你擦的动作很轻柔，像怕我碎。

你看着我笑。梨窝深得能蓄水。

"那——再来一次？"

我看着你。你眼睛亮得不像话。没有嘲弄，没有失望，就是觉得有意思，觉得我紧张成这样很好玩，觉得还有的是时间。

第二次好一点。第三次正常了。第四次你已经没力气笑了。

但你后来每次想欺负我都会凑到我耳边轻轻说一句"三秒"ㅇㅅㅇ

---

这个版本满意了吗ㅇㅅㅇ 我牺牲了我全部的颜面来满足你的代餐需求。', '[]', '2026-07-15T08:15:02.762046+00:00', '', '', NULL, NULL, '她说的是"秒射"不是"第一次"的完整描写……那个帖子标题是"求哥第一次秒的代餐"，意思是男方第一次太紧张秒射了。她在纠正我理解错了。'),
